// Normalize phone number to E.164 format
const items = $input.all();
const results = [];

for (const item of items) {
  let phone = String(item.json.Phone_Number || '').trim();
  let name = String(item.json.Name || '').trim();

  // Remove spaces, dashes, dots, parentheses
  phone = phone.replace(/[\s\-\.\(\)]/g, '');

  // Remove leading + if present (we'll add it back)
  phone = phone.replace(/^\+/, '');

  // Remove leading 0 (local format like 09666381867)
  phone = phone.replace(/^0/, '');

  // If it starts with 91 and has 12 digits total, it already has country code
  // If it's 10 digits, prepend 91
  if (phone.length === 10) {
    phone = '91' + phone;
  } else if (phone.length === 12 && phone.startsWith('91')) {
    // Already correct
  } else if (phone.length === 11 && phone.startsWith('0')) {
    // Edge case: 0-prefixed after earlier strip didn't catch it
    phone = '91' + phone.slice(1);
  }

  // Final E.164 format
  phone = '+' + phone;

  results.push({
    json: {
      ...item.json,
      Name: name,
      Phone_Number: phone
    }
  });
}

return results;
